    path = []

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and not visited[r][c]

    def backtrack(r, c):
        visited[r][c] = True
        path.append((r, c))
        if (r, c) == goal:
            return True
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                if backtrack(nr, nc):
                    return True
        path.pop()
        return False

    if backtrack(start_row, start_col):
        return path
    return []

