def solve(nums, k):
    def count_less_equal(x):
        cnt = 0
        for num in nums:
            if num <= x:
                cnt += 1
        return cnt

    left, right = min(nums), max(nums)
    while left < right:
        mid = (left + right) // 2
        if count_less_equal(mid) < k:
            left = mid + 1
        else:
            right = mid
    return left

